with with_windows as (select id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, first_value(humidity, true) over (partition by device_code order by status_bits, id rows between unbounded preceding and current row) as first_known_humidity, avg(humidity) over (partition by device_code order by cast(reading_ts as bigint) range between 1800 preceding and current row) as humidity_avg_30m, count(pressure) over (partition by device_code order by cast(reading_ts as bigint) range between 3600 preceding and current row) as pressure_count_1h from device_readings) select id, temp_c, humidity, status_bits, firmware, first_known_humidity, humidity_avg_30m, pressure_count_1h from with_windows order by pressure_count_1h desc nulls last, humidity_avg_30m
